// fastest.mjs: the Fastest option, the quickest way to ride between two points whatever the traffic.
//
// Its cost is riding time in seconds: every 20 m road piece (atom) costs its length / speed, plus time for climbing,
// for the traffic signals along it and for the junctions it passes. The ordinary route search (best-route.mjs) finds
// it with these as the weights (weights.mjs atomMultiplier with P.fast: seconds per metre) and the junction model
// (turns.mjs) with FAST_TURNS (seconds). Traffic, tunnels, road-type taste, "Avoid tunnels" and the detour limit play
// no part: a rider who wants the quickest way rides the shoulder of a trunk road.
//
// Calibrated on the owner's own commute across west Tokyo, 11.8 km, ridden in about 50 minutes (60 on the way back,
// uphill and at the evening rush): back streets, a cycle track, then the leftmost lane of two trunk roads, on the
// side road where the main lanes dive under a junction. With these values the search follows 97% of that line
// within 30 m and 87% carriageway by carriageway (test/fastest.mjs, the line kept outside git), and gives 51.5 min
// out and 55 back. What decides the route most is the stop time (signals at 35 s instead of 20, or no junction time,
// take it off the trunk road) and the speed of main roads against back streets (at 22 vs 18 km/h it takes 1 km of
// back streets beside the trunk road).
//
// Speeds (km/h) are the rider's average over a stretch, small stops included. A bike rides the leftmost lane
// whatever the road's width, so every arterial (trunk, primary, secondary) has one speed: four lanes under an
// expressway are no quicker than the two-lane side road beside them. A sidewalk is ridden (slowly: pedestrians,
// driveways, kerbs) where that is quicker.
// Limits (owner, 2026-11-17): never against a one-way on a real road (osm-tags.mjs bikeOneway, for every route), and
// a main road's lanes below ground (an underpass, a cutting: graph atomBelow) cost belowS a metre more, so the route
// stays on the surface road beside them; a long tunnel with no way round is still ridden.
export const FAST = {
  kmh: { arterial: 24, tertiary: 20.5, local: 16.5, narrow: 14.5, track: 12.5, cycleway: 22, shared: 14, sidewalk: 11.5, foot: 10.5, dismount: 5 },
  belowS: 0.5,   // an underpass or cutting on a main road: x4 the time
  unpaved: 0.8,  // x speed on an unpaved surface
  stairsS: 60,   // a flight of stairs, carried
  upS: 8,        // seconds per metre climbed (about 120 W for a rider and bike of 85 kg)
  downS: 2,      // seconds saved per metre descended, at most 30% of the piece's time (braking, lights at the bottom)
  signalS: 17,   // a traffic signal: the mean wait (red about half the time, a cycle of about 70 s)
};
// Junction time (seconds, turns.mjs junctionModel): a junction slows the rider a little, a turn a little more; a
// signal costs signalS, and a right turn there is made in two stages (二段階右折: across, then wait at the far corner
// for the second light). Without signals, crossing or turning right across a busy road means waiting for a gap.
export const FAST_TURNS = {
  scale: 1, straight: 2, slight: 2, left: 3, right: 4, sharp: 1.5, uturn: 20, signal: FAST.signalS, twoStage: 20,
  busy: [[3000, 0], [7000, 4], [15000, 8], [25000, 15]], wide: 1.5, leftMerge: 0.4, majorV: 6000,
  nodeSignals: true, // a junction with signals mapped on it (graph nodeSignal) counts as signalled
  signalGapM: 40,    // a second signal within 40 m (the far carriageway of a divided road) is the same stop
};

// The weights of the Fastest search from the rider's weights: only the roads they avoided (noteF) carry over.
export const fastParams = (params = {}) => ({ fast: FAST, turns: FAST_TURNS, noteF: params.noteF ?? null, avoidTunnels: false });

const kmhOf = (rc, flags, K) => {
  if ((flags & 48) === 32) return K.dismount; // bicycle=dismount: pushed
  if (rc <= 4) return K.arterial;
  if (rc <= 6) return K.tertiary;
  if (rc <= 8) return K.local;
  if (rc === 9) return K.narrow;
  if (rc === 10) return K.track;
  if (rc === 11) return K.cycleway;
  if (rc === 13) return K.shared;
  return flags & 64 ? K.sidewalk : K.foot;
};
// Seconds per metre of atom i, travelled uphill (dir > 0), downhill (< 0) or level (0).
export function fastSecPerM(graph, i, F = FAST, dir = 0) {
  const flags = graph.atomFlags[i], len = Math.max(1, graph.atomLen[i]);
  const signals = graph.atomSignal ? graph.atomSignal[i] * F.signalS / len : 0;
  if (flags & 16) return F.stairsS / len + signals;
  let v = kmhOf(graph.atomRc[i], flags, F.kmh) / 3.6;
  if (flags & 8) v *= F.unpaved;
  const t = 1 / v, g = graph.atomGrade[i] / 1e4;
  const climb = dir > 0 ? F.upS * g : dir < 0 ? -Math.min(F.downS * g, 0.3 * t) : 0;
  return t + climb + signals + (graph.atomBelow?.[i] ? F.belowS : 0);
}

// "≈ 50 min" from seconds
export const fmtMin = (s) => (s >= 5940 ? `${Math.floor(s / 3600)} h ${String(Math.round((s % 3600) / 60)).padStart(2, '0')}` : `${Math.max(1, Math.round(s / 60))} min`);
