// Road-graph circuit model: corridor selection and the wasm solver wrapper, on the typed graph
// (web/CONTRACT.md §2/§4). Weights live in weights.mjs. Works in the browser and in Node (for tests).
import { atomMultiplier, DEFAULTS } from './weights.mjs';
import { corridor, stopPoints } from './route.mjs';

export { DEFAULTS };

export async function loadSolver(source) {
  const bytes = source instanceof ArrayBuffer || ArrayBuffer.isView(source) ? source : await (await fetch(source)).arrayBuffer();
  const { instance } = await WebAssembly.instantiate(bytes, {});
  return instance.exports;
}

const projector = (lon0, lat0) => {
  const kx = Math.cos((lat0 * Math.PI) / 180) * 111320, ky = 110574;
  return ([lon, lat]) => [(lon - lon0) * kx, (lat - lat0) * ky];
};

// Union-find components over selected chains; returns Int32Array of component roots per local node.
function components(graph, local, n, chains) {
  const par = Int32Array.from({ length: n }, (_, i) => i);
  const find = (i) => { while (par[i] !== i) i = par[i] = par[par[i]]; return i; };
  for (const c of chains) { const a = find(local[graph.chainA[c]]), b = find(local[graph.chainB[c]]); if (a !== b) par[a] = b; }
  return Int32Array.from({ length: n }, (_, i) => find(i));
}

// Generic selection from a node predicate on local metres (x, y). `proj` maps [lon, lat] -> [x, y].
export function selectNodes(graph, proj, keep) {
  const local = new Int32Array(graph.nNodes).fill(-1);
  const xs = [], ys = [], global = [];
  for (let i = 0; i < graph.nNodes; i++) {
    const [x, y] = proj([graph.nodeLon[i], graph.nodeLat[i]]);
    if (keep(x, y, i)) { local[i] = xs.length; xs.push(x); ys.push(y); global.push(i); }
  }
  const chains = [];
  for (let c = 0; c < graph.nChains; c++) {
    const a = graph.chainA[c], b = graph.chainB[c];
    if (a !== b && local[a] >= 0 && local[b] >= 0) chains.push(c);
  }
  const comp = components(graph, local, xs.length, chains);
  return { local, global, x: Float64Array.from(xs), y: Float64Array.from(ys), chains, comp, proj };
}

// Nodes within bufferM of a route, and chains with both ends inside.
//   selectCorridor(graph, line, bufferM)    line = [[lon,lat],...] or multi-part [[[lon,lat],...], ...]
//   selectCorridor(graph, A, B, bufferM)    the original two-point form (a capsule)
// sel.A / sel.B are the route's first / last point (local metres); sel.waypoints every point in order.
export function selectCorridor(graph, lineOrA, bOrBuffer, maybeBuffer) {
  const twoPoint = typeof bOrBuffer !== 'number';
  const C = corridor(twoPoint ? [lineOrA, bOrBuffer] : lineOrA, twoPoint ? maybeBuffer : bOrBuffer);
  const sel = selectNodes(graph, C.proj, (x, y) => C.dist(x, y) <= C.bufM);
  return { ...sel, A: C.proj(C.first), B: C.proj(C.last), waypoints: C.points.map(C.proj), parts: C.parts, bufferM: C.bufM };
}
// Does the corridor's road network fall apart between the route's points (a river with no bridge inside the search
// width, say)? Each point is matched to the nearest junction of a piece that holds at least 2% of the corridor's
// junctions, so a parking lot or a stray footpath near a point does not count as a piece of its own.
export function corridorSplit(sel) {
  const n = sel.x.length; if (!n || !(sel.waypoints?.length >= 2)) return false;
  const size = new Map(); for (let i = 0; i < n; i++) size.set(sel.comp[i], (size.get(sel.comp[i]) ?? 0) + 1);
  const min = Math.max(50, 0.02 * n);
  const pieceOf = ([px, py]) => {
    let bi = -1, bd = Infinity;
    for (let i = 0; i < n; i++) { if (size.get(sel.comp[i]) < min) continue; const d = (sel.x[i] - px) ** 2 + (sel.y[i] - py) ** 2; if (d < bd) { bd = d; bi = i; } }
    return bi < 0 ? null : sel.comp[bi];
  };
  const pieces = sel.waypoints.map(pieceOf);
  return pieces.some((c) => c !== pieces[0]);
}

// Nodes inside a lon/lat box [west, south, east, north], and chains with both ends inside: the selection for
// Everywhere ↔ everywhere over an analysis box (no route, so no A / B or waypoints).
export function selectBox(graph, box) {
  const [w, s, e, n] = box, proj = projector((w + e) / 2, (s + n) / 2);
  const [x0, y0] = proj([w, s]), [x1, y1] = proj([e, n]);
  const sel = selectNodes(graph, proj, (x, y) => x >= x0 && x <= x1 && y >= y0 && y <= y1);
  return { ...sel, waypoints: [], parts: [], bufferM: 0, box };
}

function upload(ex, arrays) {
  ex.reset();
  const ptr = {};
  for (const [k, a] of Object.entries(arrays)) ptr[k] = ex.alloc(a.byteLength);
  for (const [k, a] of Object.entries(arrays)) new a.constructor(ex.memory.buffer, ptr[k], a.length).set(a);
  return ptr;
}

// Build edge arrays for the selection with a given per-atom multiplier function mult(atomIndex).
// segM > 0 splits chains into ~segM pieces with extra degree-2 nodes, so trips start all along roads
// (like Omniscape's block_size grid) rather than only at junctions. Chain current = length-weighted mean.
function edges(graph, sel, mult, segM = 0) {
  const xs = Array.from(sel.x), ys = Array.from(sel.y), comp = Array.from(sel.comp);
  const eu = [], ev = [], eg = [], echain = [], elen = [];
  const w = new Array(xs.length).fill(0);
  sel.chains.forEach((c, e) => {
    const a0 = graph.atomStart[c], a1 = graph.atomStart[c + 1];
    let total = 0;
    for (let i = a0; i < a1; i++) total += graph.atomLen[i];
    const parts = segM > 0 ? Math.max(1, Math.round(total / segM)) : 1;
    // chain geometry in local metres, for placing intermediate nodes
    let pos = null;
    if (parts > 1) {
      const pts = [];
      for (let i = graph.coordStart[c]; i < graph.coordStart[c + 1]; i++) pts.push(sel.proj([graph.coordLon[i], graph.coordLat[i]]));
      const cum = [0];
      for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
      const scale = cum[cum.length - 1] / total;
      pos = (d) => {
        const s = d * scale; let i = 1;
        while (i < cum.length - 1 && cum[i] < s) i++;
        const f = cum[i] > cum[i - 1] ? (s - cum[i - 1]) / (cum[i] - cum[i - 1]) : 0;
        return [pts[i - 1][0] + f * (pts[i][0] - pts[i - 1][0]), pts[i - 1][1] + f * (pts[i][1] - pts[i - 1][1])];
      };
    }
    let from = sel.local[graph.chainA[c]], R = 0, S = 0, L = 0, done = 0, k = 1;
    for (let i = a0; i < a1; i++) {
      const len = graph.atomLen[i], f = mult(i);
      R += len * f; S += len / f; L += len; done += len;
      const last = i === a1 - 1;
      if (!last && done < (total * k) / parts) continue;
      let to = sel.local[graph.chainB[c]];
      if (!last) { const [x, y] = pos(done); to = xs.length; xs.push(x); ys.push(y); comp.push(sel.comp[sel.local[graph.chainA[c]]]); w.push(0); k++; }
      eu.push(from); ev.push(to); eg.push(1 / R); echain.push(e); elen.push(L);
      w[from] += S / 2; w[to] += S / 2; // source strength ~ sum of 1/resistance along the road (source_from_resistance)
      from = to; R = 0; S = 0; L = 0;
    }
  });
  return { eu: Int32Array.from(eu), ev: Int32Array.from(ev), eg: Float64Array.from(eg), w: Float64Array.from(w),
    x: Float64Array.from(xs), y: Float64Array.from(ys), comp: Int32Array.from(comp), echain, elen };
}

// sub-edge currents -> one value per selected chain (length-weighted mean)
function perChain(E, cur, m) {
  const out = new Float64Array(m), len = new Float64Array(m);
  for (let i = 0; i < cur.length; i++) { out[E.echain[i]] += cur[i] * E.elen[i]; len[E.echain[i]] += E.elen[i]; }
  for (let e = 0; e < m; e++) if (len[e] > 0) out[e] /= len[e];
  return out;
}

// Target blocks (Omniscape's block_size on a graph): when there are more than maxTargets source nodes, group them
// into square blocks; the strongest node of each block is the target and carries the block's total source strength,
// so the total current injected is unchanged. Every node still acts as a source. maxTargets <= 0 = exact (all nodes).
export function targetStrengths(E, maxTargets) {
  const n = E.x.length, tw = new Float64Array(n);
  const src = []; for (let i = 0; i < n; i++) if (E.w[i] > 0) src.push(i);
  if (!(maxTargets > 0) || src.length <= maxTargets) { for (const i of src) tw[i] = E.w[i]; return { tw, blockM: 0 }; }
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const i of src) { x0 = Math.min(x0, E.x[i]); x1 = Math.max(x1, E.x[i]); y0 = Math.min(y0, E.y[i]); y1 = Math.max(y1, E.y[i]); }
  let size = Math.sqrt(((x1 - x0 + 1) * (y1 - y0 + 1)) / maxTargets), blocks;
  for (let iter = 0; iter < 12; iter++) { // grow the block until the number of non-empty blocks fits
    blocks = new Map();
    for (const i of src) {
      const k = `${E.comp[i]}:${Math.floor((E.x[i] - x0) / size)}:${Math.floor((E.y[i] - y0) / size)}`;
      const b = blocks.get(k);
      if (!b) blocks.set(k, { best: i, sum: E.w[i] }); else { b.sum += E.w[i]; if (E.w[i] > E.w[b.best]) b.best = i; }
    }
    if (blocks.size <= maxTargets) break;
    size *= Math.sqrt(blocks.size / maxTargets) * 1.05;
  }
  for (const b of blocks.values()) tw[b.best] = b.sum;
  return { tw, blockM: size };
}

function solveOmni(ex, E, radiusM, tw) {
  const n = E.x.length, m = E.eu.length;
  const meanG = E.eg.reduce((s, g) => s + g, 0) / Math.max(1, m);
  const p = upload(ex, { eu: E.eu, ev: E.ev, eg: E.eg, w: E.w, tw, x: E.x, y: E.y, comp: E.comp, cur: new Float64Array(m) });
  const nnz = ex.factor(n, m, p.eu, p.ev, p.eg, meanG * 1e-9, p.x, p.y); // nested-dissection ordering
  if (nnz < 0) throw new Error('factorization failed');
  const targets = ex.omni(p.w, p.tw, p.x, p.y, p.comp, radiusM, p.cur);
  return { cur: new Float64Array(ex.memory.buffer, p.cur, m).slice(), nnz, targets, n };
}

// Exact reduction for point-to-point solves: only the stops' component matters; dead-end trees carry no current
// between two points (prune leaves repeatedly), and a run of degree-2 junctions is one series resistor carrying a
// single current (contract it). Returns the reduced system plus edgeMap (original edge -> reduced edge, -1 = no current).
export function reduceForPair(E, keep, compId) {
  const n = E.x.length, m = E.eu.length;
  const alive = new Uint8Array(m), deg = new Int32Array(n);
  for (let e = 0; e < m; e++) {
    const a = E.eu[e], b = E.ev[e];
    if (a === b || E.comp[a] !== compId) continue;
    alive[e] = 1; deg[a]++; deg[b]++;
  }
  // adjacency (CSR) over alive edges
  const start = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) start[i + 1] = start[i] + deg[i];
  const adjE = new Int32Array(start[n]), fill = start.slice(0, n);
  for (let e = 0; e < m; e++) if (alive[e]) { adjE[fill[E.eu[e]]++] = e; adjE[fill[E.ev[e]]++] = e; }
  const isKeep = new Uint8Array(n); for (const k of keep) if (k >= 0) isKeep[k] = 1;
  // 1) prune leaves
  const queue = [];
  for (let i = 0; i < n; i++) if (deg[i] === 1 && !isKeep[i]) queue.push(i);
  while (queue.length) {
    const v = queue.pop();
    if (deg[v] !== 1) continue;
    for (let q = start[v]; q < start[v + 1]; q++) {
      const e = adjE[q]; if (!alive[e]) continue;
      alive[e] = 0; deg[v]--;
      const u = E.eu[e] === v ? E.ev[e] : E.eu[e];
      deg[u]--;
      if (deg[u] === 1 && !isKeep[u]) queue.push(u);
      break;
    }
  }
  // 2) contract degree-2 runs between junctions (deg != 2, or a stop)
  const junction = (v) => deg[v] > 0 && (deg[v] !== 2 || isKeep[v]);
  const newId = new Int32Array(n).fill(-1);
  const xs = [], ys = [];
  for (let v = 0; v < n; v++) if (junction(v)) { newId[v] = xs.length; xs.push(E.x[v]); ys.push(E.y[v]); }
  const edgeMap = new Int32Array(m).fill(-1);
  const eu = [], ev = [], eg = [];
  for (let v = 0; v < n; v++) {
    if (!junction(v)) continue;
    for (let q = start[v]; q < start[v + 1]; q++) {
      let e = adjE[q];
      if (!alive[e] || edgeMap[e] !== -1) continue;
      const id = eu.length, members = [];
      let node = v, R = 0;
      for (;;) {
        members.push(e); R += 1 / E.eg[e];
        node = E.eu[e] === node ? E.ev[e] : E.eu[e];
        if (junction(node)) break;
        let nextE = -1; // the other alive edge of this degree-2 node
        for (let r = start[node]; r < start[node + 1]; r++) { const f = adjE[r]; if (alive[f] && f !== e) { nextE = f; break; } }
        if (nextE < 0) break;
        e = nextE;
      }
      for (const f of members) edgeMap[f] = node === v ? -2 : id; // a loop back to v carries no current
      if (node === v) continue;
      eu.push(newId[v]); ev.push(newId[node]); eg.push(1 / R);
    }
  }
  for (let e = 0; e < m; e++) if (edgeMap[e] === -2) edgeMap[e] = -1;
  return { n: xs.length, eu: Int32Array.from(eu), ev: Int32Array.from(ev), eg: Float64Array.from(eg),
    x: Float64Array.from(xs), y: Float64Array.from(ys), newId, edgeMap };
}

// mode 'omni': everywhere-to-everywhere within the selection (plus flow potential / normalized current)
// mode 'pair': 1 A from the node nearest the first route point to the node nearest the last (same component).
//   via: true (every waypoint) or an array of waypoint indices (pinned points) routes through them in order instead: 1 A for each consecutive pair, |currents| summed.
export function run(ex, graph, sel, { mode = 'omni', radiusM = 5000, params = DEFAULTS, segM = 0, via = false, maxTargets = 1500 } = {}) {
  const t0 = performance.now();
  const n = sel.x.length, m = sel.chains.length;
  if (!m) return { cur: new Float64Array(0), flow: new Float64Array(0), norm: new Float64Array(0), ms: 0, n, m, targets: 0 };
  const mult = (i) => atomMultiplier(graph, i, params);
  if (mode === 'pair') {
    const E = edges(graph, sel, mult);
    const nearest = ([px, py], compFilter) => {
      let best = -1, bd = Infinity;
      for (let i = 0; i < n; i++) {
        if (E.w[i] <= 0 || (compFilter != null && sel.comp[i] !== compFilter)) continue;
        const d = Math.hypot(sel.x[i] - px, sel.y[i] - py);
        if (d < bd) { bd = d; best = i; }
      }
      return best;
    };
    const s = nearest(sel.A), comp = s >= 0 ? sel.comp[s] : null;
    const t = s >= 0 ? nearest(sel.B, comp) : -1;
    const P = s >= 0 ? stopPoints(sel, via) : [];
    const stops = P.length > 2 ? P.map((w, k) => (k === 0 ? s : k === P.length - 1 ? t : nearest(w, comp))) : [s, t];
    const cur = new Float64Array(m);
    if (s < 0 || t < 0) return { cur, s, t, stops, legs: 0, nnz: 0, n, m, ms: performance.now() - t0 };
    const R = reduceForPair(E, stops, sel.comp[s]); // exact: prune dead ends, contract series runs
    const m2 = R.eu.length;
    if (!m2) return { cur, s, t, stops, legs: 0, nnz: 0, n, m, reducedN: R.n, reducedM: 0, ms: performance.now() - t0 };
    const meanG = R.eg.reduce((acc, g) => acc + g, 0) / m2;
    const p = upload(ex, { eu: R.eu, ev: R.ev, eg: R.eg, x: R.x, y: R.y, cur: new Float64Array(m2) });
    const nnz = ex.factor(R.n, m2, p.eu, p.ev, p.eg, meanG * 1e-9, p.x, p.y);
    if (nnz < 0) throw new Error('factorization failed');
    const cur2 = new Float64Array(m2);
    let legs = 0;
    for (let k = 1; k < stops.length; k++) {
      const a = R.newId[stops[k - 1]], b = R.newId[stops[k]];
      if (a < 0 || b < 0 || a === b) continue;
      ex.pair(a, b, p.cur);
      const leg = new Float64Array(ex.memory.buffer, p.cur, m2);
      for (let e = 0; e < m2; e++) cur2[e] += leg[e];
      legs++;
    }
    for (let e = 0; e < m; e++) { const r = R.edgeMap[e]; if (r >= 0) cur[e] = cur2[r]; }
    return { cur, s, t, stops, legs, nnz, n, m, reducedN: R.n, reducedM: m2, ms: performance.now() - t0 };
  }
  // flow potential: same sources, resistance 1 per metre (Omniscape keeps source strengths and only flattens resistance;
  // it also makes off-road pixels conductive, which has no graph equivalent, so normalized maps differ by design)
  const Es = edges(graph, sel, mult, segM), Ef = edges(graph, sel, () => 1, segM);
  Ef.w = Es.w;
  const { tw, blockM } = targetStrengths(Es, maxTargets);
  const main = solveOmni(ex, Es, radiusM, tw), flat = solveOmni(ex, Ef, radiusM, tw);
  const cur = perChain(Es, main.cur, m), flow = perChain(Ef, flat.cur, m);
  const norm = cur.map((c, e) => (flow[e] > 0 ? c / flow[e] : 0));
  return { cur, flow, norm, nnz: main.nnz, targets: main.targets, blockM, n: main.n, m, ms: performance.now() - t0 };
}

// rank in [0,1] among positive values (quantile colouring, like the QGIS styling)
export function quantileRank(values) {
  const idx = [...values.keys()].filter((i) => values[i] > 0).sort((a, b) => values[a] - values[b]);
  const q = new Float64Array(values.length);
  idx.forEach((i, r) => { q[i] = idx.length > 1 ? r / (idx.length - 1) : 1; });
  return q;
}
