// Route complexity: the cost of passing a junction, in metres of riding a flat quiet road (multiplier 1), added by
// the edge-based best-route search for each arc -> arc transition. Model and sources: research-turn-cost.md.
//   geometry  straight 5 m, slight 25 m, left 60 m, right 100 m (Japan: right turns cross traffic and are two-stage),
//             sharp x1.5, U-turn 200 m; a node where only two roads meet is a bend, not a junction (0); riding on
//             along the same road through a junction (same class, similar traffic, bends <= 100°) counts as straight
//   conflict  likely signalised junction (two major roads meet: >= 3 major road ends), or a crossing tagged with signals:
//             wait 40 m, right turn + 150 m (二段階右折 second wait);
//             otherwise crossing straight over a busier road, or turning right across traffic: busy(V) after Broach
//             et al. (0 below 3k veh/day, 110 m at 7k, 160 m at 15k, 450 m at 25k+), x1.5 over a divided / >= 19.5 m road;
//             a left turn merging onto a busier road: 0.4 x busy(V)
// The user's "Simple routes" slider scales everything (P.turns.scale; 0 = no turn costs).
import { trafficV } from './weights.mjs';

export const TURN_DEFAULTS = {
  scale: 1, straight: 5, slight: 25, left: 60, right: 100, sharp: 1.5, uturn: 200, signal: 40, twoStage: 150,
  busy: [[3000, 0], [7000, 110], [15000, 160], [25000, 450]], wide: 1.5, leftMerge: 0.4, majorV: 6000,
};
// vehicles/day by road class when the graph has no traffic estimate
const CLASS_V = { 1: 12000, 2: 6000, 4: 3000, 6: 1500, 8: 400, 9: 100 };

export function busyCost(V, T = TURN_DEFAULTS) {
  const B = T.busy;
  if (!(V > B[0][0])) return 0;
  if (V >= B[B.length - 1][0]) return B[B.length - 1][1];
  for (let k = 1; k < B.length; k++) if (V < B[k][0]) {
    const f = (Math.log(V) - Math.log(B[k - 1][0])) / (Math.log(B[k][0]) - Math.log(B[k - 1][0]));
    return B[k - 1][1] + f * (B[k][1] - B[k - 1][1]);
  }
  return 0;
}
// signed turn angle from heading a to heading b (degrees, clockwise = positive = right turn)
export const turnAngle = (a, b) => ((((b - a + 180) % 360) + 360) % 360) - 180;

// graph: typed graph; chains: sel.chains (arc 2e = chain e A->B, 2e+1 = B->A); to/head/next: the search's arc lists
export function junctionModel(graph, chains, { to, head, next }, P = {}) {
  const T = { ...TURN_DEFAULTS, ...(P.turns ?? {}) };
  const m = chains.length, M2 = 2 * m;
  const hOut = new Float32Array(M2), hIn = new Float32Array(M2); // heading leaving the arc's start / arriving at its end
  const endV = new Float32Array(M2), endMajor = new Uint8Array(M2), endWide = new Uint8Array(M2), endRc = new Uint8Array(M2); // at the arc's END node
  const endSig = new Uint8Array(M2); // the arc ends in a crossing with signals (atomFlags 128), or (T.nodeSignals) at a node with signals
  const nodeSig = T.nodeSignals && graph.nodeSignal ? graph.nodeSignal : null;
  // arc lengths, for T.signalGapM (two signal nodes of one crossing)
  let arcLen = null;
  if (T.signalGapM > 0) { arcLen = new Float32Array(M2); for (let e = 0; e < m; e++) { let L = 0; for (let i = graph.atomStart[chains[e]]; i < graph.atomStart[chains[e] + 1]; i++) L += graph.atomLen[i]; arcLen[2 * e] = arcLen[2 * e + 1] = L; } }
  // arc e ends at a junction with signals (as cost() decides it, without the leaving arc)
  const sigAt = (e) => { const v = to[e]; if (v < 0 || nodeInfo(v) <= 2) return false; return nodeMajor[v] >= 3 || endSig[e] === 1; };
  const kx0 = Math.cos(((graph.nodeLat?.[0] ?? 36) * Math.PI) / 180) * 111320, ky = 110574;
  const vOf = (i) => { const t = graph.atomTraffic?.[i]; return t ? trafficV(t) : (CLASS_V[graph.atomRc[i]] ?? 0); };
  const wclsOf = (i) => (graph.atomAttr ? graph.atomAttr[i] & 3 : 0);
  // heading over the first / last ~20 m of a polyline (coord indices s..e-1)
  const headingFrom = (s, e, fromStart) => {
    const lon = graph.coordLon, lat = graph.coordLat, i0 = fromStart ? s : e - 1, step = fromStart ? 1 : -1;
    let j = i0 + step;
    while (j > s - 1 && j < e && Math.hypot((lon[j] - lon[i0]) * kx0, (lat[j] - lat[i0]) * ky) < 20) j += step;
    j = Math.max(s, Math.min(e - 1, j));
    const dx = (lon[j] - lon[i0]) * kx0, dy = (lat[j] - lat[i0]) * ky;
    const h = (Math.atan2(dx, dy) * 180) / Math.PI; // direction from the end point into the chain
    return fromStart ? h : h + 180; // arriving at the end: from the inner point towards the end
  };
  for (let e = 0; e < m; e++) {
    const c = chains[e], s = graph.coordStart[c], t = graph.coordStart[c + 1];
    const hA = t - s >= 2 ? headingFrom(s, t, true) : 0, hB = t - s >= 2 ? headingFrom(s, t, false) : 0;
    hOut[2 * e] = hA; hIn[2 * e] = hB; hOut[2 * e + 1] = hB + 180; hIn[2 * e + 1] = hA + 180;
    const aA = graph.atomStart[c], aB = graph.atomStart[c + 1] - 1;
    for (const [arc, i] of [[2 * e, aB], [2 * e + 1, aA]]) { // arc 2e ends at B, 2e+1 at A
      const V = vOf(i), rc = graph.atomRc[i], w = wclsOf(i);
      endV[arc] = V; endWide[arc] = w === 3 ? 1 : 0; endRc[arc] = rc; endSig[arc] = graph.atomFlags?.[i] & 128 || nodeSig?.[arc & 1 ? graph.chainA[c] : graph.chainB[c]] ? 1 : 0;
      endMajor[arc] = rc <= 9 && (V >= T.majorV || w >= 2 || (rc <= 2 && V >= 3000)) ? 1 : 0;
    }
  }
  // per node: degree (incident chains) and number of major roads; arcs out of v are head[v] .. next
  // (counted on first use: -1 = not yet)
  // nodeRoadDeg: the roads alone (classes up to 11): a sidewalk, crossing or footpath meeting a road does not make a
  // junction of it for a rider on the road
  const nodeDeg = new Int32Array(head.length).fill(-1), nodeMajor = new Int32Array(head.length), nodeRoadDeg = new Int32Array(head.length);
  const nodeInfo = (v) => {
    let d = nodeDeg[v];
    if (d < 0) { d = 0; let mj = 0, dr = 0; for (let q = head[v]; q >= 0; q = next[q]) if (to[q] >= 0) { d++; mj += endMajor[q ^ 1]; if (endRc[q ^ 1] <= 11) dr++; } nodeDeg[v] = d; nodeMajor[v] = mj; nodeRoadDeg[v] = dr; }
    return d;
  };
  // the road's own continuation through the junction for arrival arc e: the same class and similar traffic score
  // highest, then the straightest; a main road that bends 90° at a junction still continues (riding on is not a
  // turn), while a straight side road of a lower class is a turn off it
  const contCache = new Int32Array(M2).fill(-2); // -2 = not worked out yet, -1 = none
  const continuation = (e) => {
    const c = contCache[e];
    if (c !== -2) return c;
    const v = to[e], rcIn = endRc[e], Vin = endV[e]; let best = -1, bs = -Infinity;
    for (let f = head[v]; f >= 0; f = next[f]) {
      if (to[f] < 0 || f === (e ^ 1)) continue;
      const a = Math.abs(turnAngle(hIn[e], hOut[f])); if (a > 100) continue;
      const sc = -a / 45 + (endRc[f ^ 1] === rcIn ? 2.5 : 0) + (endV[f ^ 1] >= 0.5 * Vin && endV[f ^ 1] <= 2 * Vin ? 0.5 : 0);
      if (sc > bs) { bs = sc; best = f; }
    }
    contCache[e] = best; return best;
  };
  // the junction cost of arriving on arc e and leaving on arc f (both at node to[e]); detail=true returns the parts
  const keepRight = graph.meta?.driveSide === 'right';
  function cost(e, f, detail = false) {
    const v = to[e], deg = nodeInfo(v);
    if (f === (e ^ 1)) { const c = deg <= 1 ? 0 : T.uturn; return detail ? { c, kind: 'uturn' } : c; }
    if (deg <= 2 || (endRc[e] <= 11 && endRc[f ^ 1] <= 11 && nodeRoadDeg[v] <= 2)) return detail ? { c: 0, kind: 'bend' } : 0;
    const th0 = turnAngle(hIn[e], hOut[f]), cont = continuation(e) === f;
    const th = cont ? 0 : th0, a = Math.abs(th), right = th > 30, left = th < -30; // riding on along the same road: straight
    // the turn that crosses oncoming traffic: right where traffic keeps left (Japan), left where it keeps right
    // (graph.meta.driveSide, set by the live builder); T.right / T.left are the crossing / near-side costs
    const cross = keepRight ? left : right, near = keepRight ? right : left;
    let g = a <= 30 ? T.straight : a <= 60 ? T.slight : cross ? T.right : T.left;
    if (a > 135) g *= T.sharp;
    const Vin = endV[e], Vout = endV[f ^ 1]; // f ^ 1 ends at v: the leaving road's end at this junction
    // two major roads meet (one major road through a junction is 2 major ends), or the way in or out is a crossing
    // with signals
    const signal = nodeMajor[v] >= 3 || endSig[e] === 1 || endSig[f ^ 1] === 1;
    let Vx = 0, wideX = 0; // the busiest other road here; only crossing it without signals costs anything
    if (!signal && (cross || !near)) for (let q = head[v]; q >= 0; q = next[q]) { if (to[q] < 0 || q === f || q === (e ^ 1)) continue; if (endV[q ^ 1] > Vx) { Vx = endV[q ^ 1]; wideX = endWide[q ^ 1]; } }
    let x = 0, kind = a <= 30 ? 'straight' : right ? 'right' : 'left';
    // T.signalGapM: the lights of one crossing stand on each carriageway of a divided road; arriving on a short arc
    // from a junction with signals, the rider is still at that stop
    const again = signal && arcLen && arcLen[e] < T.signalGapM && sigAt(e ^ 1);
    if (again) x = cross ? T.twoStage : 0;
    else if (signal) x = T.signal + (cross ? T.twoStage : 0);
    else if (cross) { const Vc = Math.max(Vin, Vout, Vx); x = busyCost(Vc, T) * (Vc === Vx && wideX ? T.wide : 1); }
    else if (near) x = Vout > Vin ? T.leftMerge * busyCost(Vout, T) : 0;
    else if (Vx > Math.max(Vin, Vout)) x = busyCost(Vx, T) * (wideX ? T.wide : 1); // straight over a busier road
    const c = T.scale * (g + x);
    return detail ? { c, kind, angle: Math.round(th0), cont, geom: g, conflict: x, signal: signal && !again, busy: !signal && x > 0 } : c;
  }
  return { cost, scale: T.scale, nodeDeg: nodeInfo, hIn, hOut };
}
