// Module Web Worker: the route search and the circuit solves, off the page's thread, so the map and the panel stay
// usable while a big corridor or box is worked out.
//
// The worker keeps its own copy of the road graph (sent once per graph, not per solve), the wasm solver, the last
// selection and, with it, the route search's setup (best-route.mjs keeps that with the selection), so a re-route for
// another detour limit or turn-cost scale starts at once. A solve runs to the end without reading messages: to stop
// one, the page ends the worker and starts another, which gets the graph again.
//
// Protocol:
//   in:  { type: 'init', wasm }                 URL of dist/solver.wasm
//        { type: 'graph', graph }               the typed graph (CONTRACT.md section 2); replaces the last one
//        { id, type: 'solve', mode: 'pair' | 'omni', route | box, bufM, params, via, radiusM, current, best, prefs,
//          noteF? }                             select the corridor (route, bufM) or the box, then the circuit solve
//                                               (model.mjs run) if `current`, then the best route (best-route.mjs,
//                                               options `prefs`) if `best`
//        { id, type: 'route', params, via, prefs, noteF? }    the best route again on the last selection
//        prefs.fastest = { bufM }: the Fastest route (fastest.mjs) too, on a corridor of that width, added at the end of
//                                               best.alternatives ({ fastest: true, timeS }); every option gets timeS.
//                                               It depends only on the graph, the corridor, the avoided roads and via,
//                                               so it is kept and a re-route for other weights reuses it
//        { id, type: 'tree', seeds, noteF }     Snap's preview (snap-tree.mjs): the shortest-distance tree from seeds
//                                               [{ node, cost }] over the whole graph, noteF: the avoided roads' factors
//                                               per atom (Infinity: closed). Leaves the selection alone.
//        params.noteF (the avoided roads, one factor per atom: Infinity = closed) is not sent with params: `noteF` (an
//        array, or null) comes only when it has changed, and the worker keeps it
//   out: { id, type: 'selected', n }            junctions in the selection (a solve only), before the work starts
//        { id, type: 'done', n, m, chains, global, result, best, ms }   n junctions, m roads; chains (with `current`)
//                                               and global: the selection's chain and node numbers in the graph;
//                                               result: what run returned, or null; best: the route, { error } or null
//        { id, type: 'tree', dist, via }        the tree (Float64Array, Int32Array: snap-tree.mjs distanceTree)
//        { id, type: 'stale' }                  'route' with no selection (a new worker): send a 'solve'
//        { id, type: 'error', message }
import { loadSolver, selectCorridor, selectBox, run, corridorSplit } from './model.mjs';
import { lowestResistanceRoute } from './best-route.mjs';
import { fastParams } from './fastest.mjs';
import { distanceTree } from './snap-tree.mjs';

let solver = null, graph = null, sel = null, selKey = null, split = false, noteF = null, noteRun = null;
let fastSel = null, fastSelKey = null, fastRoute = null, fastKey = null, lastRoute = null; // the Fastest route's corridor and result
self.onmessage = async (ev) => {
  const m = ev.data;
  if (m.type === 'init') { solver = loadSolver(m.wasm); return; }
  if (m.type === 'graph') { graph = m.graph; sel = null; selKey = null; noteF = null; fastSel = null; fastSelKey = null; fastRoute = null; fastKey = null; return; }
  if (m.type === 'tree') {
    try { const t = distanceTree(graph, m.seeds, m.noteF); self.postMessage({ id: m.id, type: 'tree', dist: t.dist, via: t.via }, [t.dist.buffer, t.via.buffer]); }
    catch (e) { self.postMessage({ id: m.id, type: 'error', message: e?.message ?? String(e) }); }
    return;
  }
  try {
    const t0 = performance.now();
    if (m.noteF !== undefined) { noteF = m.noteF; noteRun = null; }
    const params = { ...m.params, noteF };
    if (m.type === 'solve') {
      const key = JSON.stringify([m.box ?? m.route, m.bufM]);
      if (key !== selKey) { sel = m.box ? selectBox(graph, m.box) : selectCorridor(graph, m.route, m.bufM); selKey = key; split = !m.box && corridorSplit(sel); }
      self.postMessage({ id: m.id, type: 'selected', n: sel.x.length });
    } else if (!sel) { self.postMessage({ id: m.id, type: 'stale' }); return; }
    if (m.spin) { const end = performance.now() + m.spin; while (performance.now() < end); } // test hook (smoke-solve.mjs): a solve that takes this long
    const t1 = performance.now();
    let result = null, best = null;
    // the circuit has no closed roads: an avoided road (Infinity) is only very costly there
    if (m.type === 'solve' && m.current && sel.chains.length) { noteRun ??= noteF && noteF.map((v) => (v === Infinity ? 1e4 : v)); result = run(await solver, graph, sel, { mode: m.mode, radiusM: m.radiusM, params: { ...params, noteF: noteRun }, via: m.via }); }
    const t2 = performance.now();
    if (m.type === 'solve') lastRoute = m.route ?? null;
    const { fastest, ...prefs } = m.prefs ?? {}, fp = fastest && lastRoute ? fastParams(params) : null;
    if (m.best && sel.chains.length) { try { best = lowestResistanceRoute(graph, sel, params, { via: m.via, ...prefs, evalParams: fp }); } catch (e) { console.error(e); best = { error: e.message }; } }
    if (fp && best && !best.error) { try { addFastest(best, fastest.bufM, params, fp, m.via); } catch (e) { console.error(e); } }
    const t3 = performance.now();
    const chains = result ? Int32Array.from(sel.chains) : null, global = m.type === 'solve' ? Int32Array.from(sel.global) : null;
    self.postMessage({ id: m.id, type: 'done', n: sel.x.length, m: sel.chains.length, split, chains, global, result, best,
      ms: { select: t1 - t0, current: t2 - t1, route: t3 - t2, total: t3 - t0 } },
    [chains, global, result?.cur, result?.flow, result?.norm].filter(Boolean).map((a) => a.buffer));
  } catch (e) {
    self.postMessage({ id: m.id, type: 'error', message: e?.message ?? String(e) });
  }
};

// The Fastest route on its own (wider) corridor, kept while the graph, corridor, avoided roads and via stay the same.
// It goes at the end of best.alternatives; the rider's routes carry their time (evalCost under the Fastest weights).
function addFastest(best, bufM, params, fp, via) {
  for (const r of [best, ...best.alternatives]) if (r.evalCost != null) r.timeS = r.evalCost;
  const sk = JSON.stringify([lastRoute, bufM]);
  if (sk !== fastSelKey) { fastSel = selectCorridor(graph, lastRoute, bufM); fastSelKey = sk; fastRoute = null; }
  const key = JSON.stringify(via ?? false);
  if (!fastRoute || fastKey !== key || fastRoute.noteF !== noteF) {
    const r = lowestResistanceRoute(graph, fastSel, fp, { via, maxDetour: Infinity, alternatives: 0, tunnelAlt: false, evalParams: params, cache: false });
    fastRoute = { noteF, r: r && !r.error && r.coords?.length >= 2 ? r : null }; fastKey = key;
  }
  const f = fastRoute.r; if (!f) return;
  // its cost under the rider's weights (the options list compares costs), and how much of it the rider's best route rides
  const onBest = new Set(best.chains); let shared = 0, L = 0;
  for (const c of f.chains) { let l = 0; for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) l += graph.atomLen[i]; L += l; if (onBest.has(c)) shared += l; }
  best.alternatives.push({ ...f, fastest: true, timeS: f.resistance, resistance: f.evalCost, meanMultiplier: f.lengthM ? f.evalRoad / f.lengthM : 0,
    sharingPct: Math.round(100 * shared / (L || 1)), evalCost: undefined, evalRoad: undefined, alternatives: undefined });
}
